import heapq


def dijkstra(graph, start):
    """Find shortest paths from start to all other nodes in a weighted graph."""
    distances = {node: float("inf") for node in graph}
    distances[start] = 0
    previous = {node: None for node in graph}
    pq = [(0, start)]

    while pq:
        current_dist, current_node = heapq.heappop(pq)
        if current_dist > distances[current_node]:
            continue
        for neighbor, weight in graph[current_node].items():
            distance = current_dist + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                previous[neighbor] = current_node
                heapq.heappush(pq, (distance, neighbor))

    return distances, previous


def shortest_path(graph, start, end):
    """Get the shortest path and its distance between two nodes."""
    distances, previous = dijkstra(graph, start)
    if distances[end] == float("inf"):
        return None, float("inf")
    path = []
    node = end
    while node is not None:
        path.append(node)
        node = previous[node]
    return path[::-1], distances[end]


if __name__ == "__main__":
    # Test graph: adjacency dict with weighted edges
    graph = {
        "A": {"B": 4, "C": 1},
        "B": {"A": 4, "C": 2, "D": 5},
        "C": {"A": 1, "B": 2, "D": 8, "E": 10},
        "D": {"B": 5, "C": 8, "E": 2},
        "E": {"C": 10, "D": 2},
    }

    distances, previous = dijkstra(graph, "A")

    print("Shortest distances from A:")
    for node, dist in sorted(distances.items()):
        print(f"  A -> {node}: {dist}")

    print()
    for end in sorted(graph):
        if end == "A":
            continue
        path, dist = shortest_path(graph, "A", end)
        print(f"  A -> {end}: path = {' -> '.join(path)}, distance = {dist}")
